#!/usr/bin/env python3
import base64
import sys
from pathlib import Path

root = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path.cwd()
activity = root / "overlay/src/main/java/org/yuzu/yuzu_emu/gamedeck/GameDeckActivity.kt"
res_dir = root / "overlay/src/main/res/drawable-nodpi"
res_dir.mkdir(parents=True, exist_ok=True)
(res_dir / "gamedeck_menu_bg.webp").write_bytes(base64.b64decode(""))

text = activity.read_text(encoding="utf-8")

if "import org.yuzu.yuzu_emu.R\\n" not in text:
    first_import = text.find("import ")
    if first_import < 0:
        raise SystemExit("GameDeck import block not found")
    text = text[:first_import] + "import org.yuzu.yuzu_emu.R\\n" + text[first_import:]

marker = """        root.addView(buildBottomNavigation())
        setContentView(root)
"""
replacement = """        // Subtle GameDeck menu wallpaper with a dark readability layer.
        val backgroundBitmap = android.graphics.BitmapFactory.decodeResource(
            resources,
            R.drawable.gamedeck_menu_bg
        )
        val backgroundDrawable = android.graphics.drawable.BitmapDrawable(
            resources,
            backgroundBitmap
        ).apply {
            gravity = Gravity.FILL
            alpha = 215
        }
        val dimLayer = android.graphics.drawable.ColorDrawable(
            Color.argb(150, 2, 10, 18)
        )
        root.background = android.graphics.drawable.LayerDrawable(
            arrayOf(backgroundDrawable, dimLayer)
        )

        root.addView(buildBottomNavigation())
        setContentView(root)
"""
if marker not in text:
    raise SystemExit("GameDeck root marker not found")
text = text.replace(marker, replacement, 1)

activity.write_text(text, encoding="utf-8")
print("GameDeck v6 global menu background patch applied.")
